import{_ as t,c as n,j as e,a as _,o as l}from"./chunks/framework.CqbvlPrP.js";const u=JSON.parse('{"title":"第九十五章 大河只剩下二、三滴水","description":"","frontmatter":{},"headers":[],"relativePath":"meditation/巴利文大藏经/95第九十五章 大河只剩下二、三滴水.md","filePath":"meditation/巴利文大藏经/95第九十五章 大河只剩下二、三滴水.md"}'),r={name:"meditation/巴利文大藏经/95第九十五章 大河只剩下二、三滴水.md"};function o(s,a,i,d,p,c){return l(),n("div",null,a[0]||(a[0]=[e("h1",{id:"第九十五章-大河只剩下二、三滴水",tabindex:"-1"},[_("第九十五章 大河只剩下二、三滴水 "),e("a",{class:"header-anchor",href:"#第九十五章-大河只剩下二、三滴水","aria-label":'Permalink to "第九十五章 大河只剩下二、三滴水"'},"​")],-1),e("p",null,"完全读懂巴利文大藏经",-1),e("p",null,"相应部13相应4经/合流水经第二(现观相应/因缘篇/如来记说)",-1),e("p",null,"有个时候，佛陀住在舍卫城的祇树林给孤独园。有一天，佛陀对出家弟子们说：“弟子们，恒河、耶牟那河、阿致罗筏底河、萨罗浮河、摩醯河交汇、合流、汇集的地方会有很多的水，如果这些大河交汇的水除了二、三滴水外，全部都干涸、干枯了，那么这些干涸、干枯掉的水与剩下的二、三滴水相比，那个更多呢？”",-1),e("p",null,"出家弟子们回答：“世尊，那当然是干涸、干枯掉的河水更多哦，剩下的二、三滴水实在是比不上干涸、干枯河水的百分之一、千分之一、十万分之一。剩下的二、三滴水与干涸、干枯掉的河水相比可以忽略不计。”",-1),e("p",null,"佛陀说：“同样的道理，弟子们，具足正确见解，已经证悟初果（初果解释，见第七十章）及以上果位的圣弟子们，他们灭尽、灭除的烦恼和痛苦很多，他们灭尽的烦恼和痛苦就如同恒河、耶牟那河、阿致罗筏底河、萨罗浮河、摩醯河交汇、合流、汇集处除了二、三滴水外，全部干枯、干涸掉的水那样多，他们残留的烦恼和痛苦非常的少，他们残留的烦恼和痛苦就如同这些大河剩下的二、三滴水那样少。弟子们，也就是说已经证悟初果的圣弟子们，他们残留的烦恼和痛苦比不上他们灭尽烦恼和痛苦的百分之一、千分之一、十万分之一，他们残留的烦恼和痛苦与他们灭尽的烦恼和痛苦相比可以忽略不计。这些已经证悟初果的圣弟子们，他们最多在人间和天界往返七次，就能永远的从生死轮回中解脱出来，也就是说已经证悟初果的圣弟子们，他们最多再有七次的生死轮回，就能除灭一切的烦恼和痛苦，就能从这个世间永远的解脱出来，就能从生死轮回中永远的解脱出来。弟子们，具足正确的见解，证悟初果就能获得这么大的功德利益，明白了如来所说的正法，就能获得这么大的功德利益。”",-1),e("p",null,"佛陀说法后，听法的出家弟子们都再次的顶礼佛陀，随喜赞叹佛陀说法的无量功德，他们都按着佛陀所说的法去修行。",-1)]))}const f=t(r,[["render",o]]);export{u as __pageData,f as default};
